    if (strcmp(symbol, "wifi") == 0) return &portal_icon_wifi;
    if (strcmp(symbol, "exclude") == 0) return &portal_icon_exclude;
    if (strcmp(symbol, "last_job") == 0) return &portal_icon_last_job;
