    if (strcmp(symbol, LV_SYMBOL_FILE) == 0) return &portal_icon_file;
    if (strcmp(symbol, LV_SYMBOL_DIRECTORY) == 0) return &portal_icon_file;
    if (strcmp(symbol, LV_SYMBOL_SHUFFLE) == 0) return &portal_icon_move;
    if (strcmp(symbol, LV_SYMBOL_SETTINGS) == 0) return &portal_icon_settings;
